export type Endpoint = { "instance_path": Array<OpaqueId>; "port_id": OpaqueId; "bits"?: Array<number>; };
export type NetData = { "kind": "net"; "name"?: string; "parent": OpaqueId; "domain": "electrical" | "optical" | "thermal"; "endpoints": Array<Endpoint>; "width": number; };
export type WireData = { "kind": "wire"; "parent": OpaqueId; "net": OpaqueId; "points": Array<Point>; };
export type JunctionData = { "kind": "junction"; "parent": OpaqueId; "net": OpaqueId; "point": Point; };
/** Graphical-only: excluded from netlisting, ERC and fabricated circuit; plot links evidence without adding a device. */
export type AnnotationData = { "kind": "annotation"; "parent": OpaqueId; "annotation_type": "text" | "line" | "polyline" | "arrow" | "image" | "plot" | "measurement" | "rectangle" | "ellipse"; "points"?: Array<Point>; "text"?: string; "artifact"?: Ref; "style"?: { "color"?: string; "width"?: number; "font_size"?: number; "fill"?: string; }; "plot"?: { "run"?: OpaqueId; "signals"?: Array<string>; "x_axis"?: string; "y_axis"?: string; }; };
/** A declared task boundary port. Native formats include their codec/profile; downstream input must match kind/schema/format and exact snapshot. */
export type TaskPort = { "name": string; "kind": "source" | "artifact" | "dataset" | "model" | "config" | "result"; "schema": string; "formats": Array<string>; "required": boolean; "many": boolean; };
/** Data-bearing task-to-task contract. Logs are evidence, never normal stage inputs. */
export type TaskContract = { "task": string; "inputs": Array<TaskPort>; "outputs": Array<TaskPort>; };
export type TaskInput = { "port": string; "kind": "source" | "artifact" | "dataset" | "model" | "config" | "result"; "ref": PinnedRef; "schema": string; "format": string; "producer_run_id"?: OpaqueId; };
/** Published immutable output matches the declared output port; adoption as source is a separate edit. */
export type TaskOutput = { "port": string; "kind": "artifact" | "dataset" | "result" | "model"; "ref": PinnedRef; "schema": string; "format": string; "producer_run_id": OpaqueId; "producer_snapshot": PinnedRef; };
/** Application-owned outbound port DTO. Adapter maps this to native input; transport/framework objects never cross the boundary. */
export type TaskInvocation = { "run_id": OpaqueId; "request": RunStart; "input_lock": InputLock; "inputs": Array<TaskInput>; "profile": PinnedRef; };
export type TaskResult = { "run_id": OpaqueId; "task": string; "state": "completed" | "failed" | "cancelled" | "skipped"; "outputs": Array<TaskOutput>; "result"?: ResultBundle; "failure"?: ExecutionFailure; "skip_reason"?: string; };
export type TaskSynthesizeHdl = { "inputs"?: Array<Ref>; "settings"?: Ref; "top": string; "library"?: Ref; "frontend"?: "canvas" | "slang" | "ghdl" | "amaranth"; "output_format"?: "verilog" | "json" | "rtlil" | "spice"; };
export type TaskImplementAsic = { "inputs"?: Array<Ref>; "settings"?: Ref; "stage": "full" | "synthesis" | "floorplan" | "macro_placement" | "io_placement" | "pdn" | "global_placement" | "detailed_placement" | "placement" | "cts" | "global_routing" | "detailed_routing" | "routing" | "fill" | "signoff" | "registered_step"; "flow"?: "classic" | "chip" | "vhdl_classic"; "resume_from"?: Ref; "constraints"?: Ref; "corners"?: Array<string>; "step_id"?: string; };
