export type TaskAnalyzeTiming = { "inputs"?: Array<Ref>; "settings"?: Ref; "constraints": Ref; "corners"?: Array<string>; "checks"?: Array<"setup" | "hold" | "max_slew" | "max_capacitance" | "recovery" | "removal" | "clock_gating">; "parasitics"?: Ref; };
export type TaskAnalyzePower = { "inputs"?: Array<Ref>; "settings"?: Ref; "analysis": "power" | "ir_drop"; "activity"?: Ref; "supplies"?: Ref; "corners"?: Array<string>; };
