export type TaskExtractLayout = { "inputs"?: Array<Ref>; "settings"?: Ref; "kind": "devices" | "rc" | "connectivity"; "deck"?: Ref; "output_format"?: "spice" | "cdl" | "spef" | "json"; "hierarchical"?: boolean; "corners"?: Array<string>; };
export type TaskCharacterizeCircuit = { "inputs"?: Array<Ref>; "settings"?: Ref; "plan": Ref; "mode": "sweep" | "corners" | "monte_carlo"; "sweeps"?: Array<({ "parameter": string; "target"?: Ref; "start"?: Quantity; "stop"?: Quantity; "step"?: Quantity; "values"?: Array<Quantity>; }) & (unknown | unknown)>; "corners"?: Array<string>; "samples"?: number; "seed"?: number; };
export type TaskGenerateViews = { "inputs"?: Array<Ref>; "settings"?: Ref; "kinds": Array<"symbol" | "schematic" | "layout" | "interface" | "model" | "rtl">; "source"?: Ref; };
export type TaskGenerateNetlist = { "inputs"?: Array<Ref>; "settings"?: Ref; "format": "spice" | "cdl" | "verilog" | "vhdl" | "sax" | "json"; "top"?: string; "hierarchical"?: boolean; };
export type TaskExportDesign = { "inputs"?: Array<Ref>; "settings"?: Ref; "format": "gds" | "oasis" | "lef" | "def" | "magic" | "xschem" | "spice" | "cdl" | "verilog" | "vhdl" | "project_bundle"; "hierarchical"?: boolean; "include_sources"?: boolean; };
export type TaskCompileModel = { "inputs"?: Array<Ref>; "settings"?: Ref; "source": Ref; "format": "osdi"; "model_name"?: string; };
/** Qualified simulator-specific analyses; harmonic_balance requires a qualified Xyce path. No experimental PSS promise. Frequency/time dimensions, sweeps, excitation and measurement semantics validated before admission. */
export type TaskSimulateSpice = { "inputs"?: Array<Ref>; "settings"?: Ref; "analysis": SpiceAnalysis; "frequency"?: { "spacing": "linear" | "log"; "start": Quantity; "stop": Quantity; "points": number; }; "time"?: { "stop": Quantity; "step": Quantity; "start"?: Quantity; "max_step"?: Quantity; }; "sweeps"?: Array<({ "parameter": string; "target"?: Ref; "start"?: Quantity; "stop"?: Quantity; "step"?: Quantity; "values"?: Array<Quantity>; }) & (unknown | unknown)>; "probes"?: Array<Ref>; "excitation"?: Ref; "corner"?: string; "temperature"?: Quantity; "testbench"?: Ref; "measurements"?: Array<Ref>; "sensitivity_parameters"?: Array<string>; "pole_zero_kind"?: "poles" | "zeros" | "both"; "distortion_ratio"?: number; "fundamental"?: Quantity; "harmonics"?: number; };
/** HDL or cocotb bench execution in the selected canvas dialect. Qualified Amaranth native simulation uses the hdl bench role with Python Amaranth source; exported Verilog can instead use qualified HDL/cocotb paths. */
