export type TaskSimulateCosim = { "inputs"?: Array<Ref>; "settings"?: Ref; "analog": ViewSelection; "digital": ViewSelection; "coupling": Ref; "testbench": Ref; "time"?: { "stop": Quantity; "step": Quantity; "start"?: Quantity; "max_step"?: Quantity; }; };
export type TaskSimulateOptical = { "inputs"?: Array<Ref>; "settings"?: Ref; "analysis": "sparameters" | "op" | "ac" | "tran" | "harmonic_balance"; "wavelengths"?: { "start": Quantity; "stop": Quantity; "points": number; }; "frequency"?: { "spacing": "linear" | "log"; "start": Quantity; "stop": Quantity; "points": number; }; "time"?: { "stop": Quantity; "step": Quantity; "start"?: Quantity; "max_step"?: Quantity; }; "ports"?: Array<Ref>; "harmonics"?: number; "fundamental"?: Quantity; "testbench"?: Ref; };
export type TaskSimulateEm = { "inputs"?: Array<Ref>; "settings"?: Ref; "study": Ref; "method": "fdtd" | "fem_frequency" | "eigenmode" | "eme"; "frequency"?: { "spacing": "linear" | "log"; "start": Quantity; "stop": Quantity; "points": number; }; "ports"?: Array<Ref>; "mesh"?: Ref; "max_refinements"?: number; };
export type TaskSimulateThermal = { "inputs"?: Array<Ref>; "settings"?: Ref; "study": Ref; "analysis": "steady" | "tran"; "time"?: { "stop": Quantity; "step": Quantity; "start"?: Quantity; "max_step"?: Quantity; }; "mesh"?: Ref; };
export type TaskSimulateDevice = { "inputs"?: Array<Ref>; "settings"?: Ref; "study": Ref; "analysis": "equilibrium" | "dc" | "ac" | "tran"; "sweeps"?: Array<({ "parameter": string; "target"?: Ref; "start"?: Quantity; "stop"?: Quantity; "step"?: Quantity; "values"?: Array<Quantity>; }) & (unknown | unknown)>; "frequency"?: { "spacing": "linear" | "log"; "start": Quantity; "stop": Quantity; "points": number; }; "time"?: { "stop": Quantity; "step": Quantity; "start"?: Quantity; "max_step"?: Quantity; }; "mesh"?: Ref; };
export type TaskWorkflowAsic = { "inputs"?: Array<Ref>; "settings"?: Ref; "flow"?: "classic" | "chip" | "vhdl_classic"; "plan"?: Ref; "stop_after"?: "synthesis" | "floorplan" | "placement" | "cts" | "routing" | "signoff"; "corners"?: Array<string>; };
export type TaskWorkflowAnalog = { "inputs"?: Array<Ref>; "settings"?: Ref; "plan": Ref; "analyses"?: Array<SpiceAnalysis>; "include_layout_checks"?: boolean; "include_post_layout"?: boolean; };
export type TaskWorkflowPhotonic = { "inputs"?: Array<Ref>; "settings"?: Ref; "plan": Ref; };
export type TaskCheckSyntax = { "inputs"?: Array<Ref>; "settings"?: Ref; "deck"?: Ref; "reference"?: Ref; "candidate"?: Ref; "rules"?: Array<string>; };
export type TaskCheckConnectivity = { "inputs"?: Array<Ref>; "settings"?: Ref; "deck"?: Ref; "reference"?: Ref; "candidate"?: Ref; "rules"?: Array<string>; };
export type TaskCheckErc = { "inputs"?: Array<Ref>; "settings"?: Ref; "deck"?: Ref; "reference"?: Ref; "candidate"?: Ref; "rules"?: Array<string>; };
export type TaskCheckDrc = { "inputs"?: Array<Ref>; "settings"?: Ref; "deck"?: Ref; "reference"?: Ref; "candidate"?: Ref; "rules"?: Array<string>; };
export type TaskCheckLvs = { "inputs"?: Array<Ref>; "settings"?: Ref; "deck"?: Ref; "reference"?: Ref; "candidate"?: Ref; "rules"?: Array<string>; };
export type TaskCheckAntenna = { "inputs"?: Array<Ref>; "settings"?: Ref; "deck"?: Ref; "reference"?: Ref; "candidate"?: Ref; "rules"?: Array<string>; };
export type TaskCheckViewSync = { "inputs"?: Array<Ref>; "settings"?: Ref; "deck"?: Ref; "reference"?: Ref; "candidate"?: Ref; "rules"?: Array<string>; };
export type TaskCheckLayoutXor = { "inputs"?: Array<Ref>; "settings"?: Ref; "deck"?: Ref; "reference"?: Ref; "candidate"?: Ref; "rules"?: Array<string>; };
export type TaskCheckFormal = { "inputs"?: Array<Ref>; "settings"?: Ref; "mode": "prove" | "bmc" | "cover"; "properties"?: Array<Ref>; "assumptions"?: Array<Ref>; "depth"?: number; "solver"?: "z3" | "boolector" | "bitwuzla" | "yices"; };
export type TaskCheckEquivalence = { "inputs"?: Array<Ref>; "settings"?: Ref; "golden": ViewSelection; "candidate": ViewSelection; "assumptions"?: Array<Ref>; };
export type TaskCheckMutation = { "inputs"?: Array<Ref>; "settings"?: Ref; "tests": Array<Ref>; "max_mutations": number; "seed"?: number; };
/** Transforms are deterministic display operations on raw values, never alternative electrical results. Dimensioned dB requires an explicit reference. */
export type TraceBinding = { "signal": OpaqueId; "transform": "identity" | "real" | "imag" | "magnitude" | "phase_deg" | "phase_rad" | "magnitude_db" | "power_db"; "axis": "left" | "right"; "reference"?: Quantity; };
export type TraceView = { "id": OpaqueId; "dataset_id": OpaqueId; "name"?: string; "kind": "traces"; "x_axis": OpaqueId; "traces": Array<TraceBinding>; "slice"?: Array<{ "axis": OpaqueId; "index": number; }>; };
export type TableView = { "id": OpaqueId; "dataset_id": OpaqueId; "name"?: string; "kind": "table"; "columns"?: Array<OpaqueId>; "sort"?: Array<{ "column": OpaqueId; "direction": "ascending" | "descending"; }>; };
/** Requires actual matrix axes; data shape determines display, never solver brand or decorative choice. */
export type MatrixView = { "id": OpaqueId; "dataset_id": OpaqueId; "name"?: string; "kind": "heatmap"; "row_axis": OpaqueId; "column_axis": OpaqueId; "transform": "identity" | "real" | "imag" | "magnitude" | "phase_deg" | "phase_rad" | "magnitude_db" | "power_db"; "slice"?: Array<{ "axis": OpaqueId; "index": number; }>; };
export type MarkerView = { "id": OpaqueId; "dataset_id": OpaqueId; "name"?: string; "kind": "markers"; };
export type DigitalView = { "id": OpaqueId; "dataset_id": OpaqueId; "name"?: string; "kind": "waveform"; "signals"?: Array<OpaqueId>; "radix"?: "binary" | "hex" | "decimal" | "signed_decimal"; };
export type FieldView = { "id": OpaqueId; "dataset_id": OpaqueId; "name"?: string; "kind": "field"; "field": OpaqueId; "component"?: string; "transform"?: "identity" | "real" | "imag" | "magnitude" | "phase_deg"; "slice"?: { "axis": OpaqueId; "position": Quantity; }; };
export type DataView = (TraceView | TableView | MatrixView | MarkerView | DigitalView | FieldView | TreeView);
/** Tree descriptor: which node IDs render expanded. Expansion state is data, not renderer code. */
export type TreeView = { "id": OpaqueId; "dataset_id": OpaqueId; "name"?: string; "kind": "tree"; "expanded"?: Array<OpaqueId>; };
export type EditEntityData = (EditComponentData | EditInstanceData | EditPortData | EditSheetData | EditSymbolData | EditCellData | EditPinData | EditPinMapData | EditNetData | EditWireData | EditJunctionData | EditShapeData | EditLayerData | EditSourceData | EditScriptData | EditTestbenchData | EditAnnotationData | EditProjectData);
/** Creation presets share one component identity. Exactly one authoring owner per view; generator and manual layout are explicit variants, never competing writers. */
export type EditComponentData = { "kind": "component"; "name": string; "description"?: string; "component_type": "assembly" | "primitive" | "spice_block" | "gdsf_component" | "hdl_component"; "domains": Array<"analog" | "digital" | "photonic" | "thermal">; "ports": Array<EditId>; "parameters"?: Array<Parameter>; "models": EditModels; "views": Array<EditSourceView>; "symbol"?: EditRef; "schematic"?: EditRef; "layout"?: EditRef; "pdk"?: EditRef; "hdl_language"?: "inherit"; };
/** Every circuit component has the SPICE slot; availability is honest. Optical-only, abstract and unelaborated blocks need no invented electrical model. */
export type EditModels = { "spice": EditSpiceModel; "other"?: Array<EditSourceView>; };
export type EditSpiceModel = ({ "state": "provided"; "source": EditRef; "view"?: string; "dialect": "spice" | "ngspice" | "xyce" | "cdl"; "entry": string; "terminal_order": Array<EditId>; "port_map": Array<EditPortMapEntry>; "conditions"?: Array<EditRef>; "provenance": "authored" | "pdk_reference" | "mapped_netlist" | "extracted"; } | { "state": "derivable"; "task": string; "inputs": Array<EditRef>; "reason": string; } | { "state": "unavailable" | "not_applicable"; "reason": string; });
export type EditPortMapEntry = { "port_id": EditId; "native_name": string; "bit"?: number; "native_index"?: number; };
/** format must resolve a registered schema/capability. Multiple source files are one source set; output generated HDL does not change authoring language. */
export type EditSourceView = { "id": string; "role": "implementation" | "behavioral_model" | "layout_generator" | "schematic" | "layout" | "testbench" | "properties" | "timing" | "abstract" | "extracted" | "documentation"; "format": string; "sources": Array<EditRef>; "entry"?: string; "profile"?: EditRef; "port_map"?: Array<EditPortMapEntry>; "default_for"?: Array<string>; "authority": "authored" | "generator" | "native_source" | "model_reference" | "derived"; };
export type EditInstanceData = { "kind": "instance"; "name": string; "parent": EditId; "definition": EditRef; "parameters"?: { [key: string]: Scalar; }; "schematic_transform"?: Transform; "layout_transform"?: Transform; };
/** Declared stable interface port. Parameter/expression widths are resolved by a qualified elaborator, never arbitrary eval or query-time project execution. */
export type EditPortData = { "kind": "port"; "name": string; "owner": EditId; "domain": "electrical" | "optical" | "thermal"; "direction": "input" | "output" | "inout" | "passive"; "role"?: "signal" | "power" | "ground" | "clock" | "thermal" | "optical"; "width": PortWidth; "order"?: number; };
export type EditSheetData = { "kind": "sheet"; "name": string; "owner": EditId; "unit": "mm"; "grid": Quantity; };
export type EditSymbolData = { "kind": "symbol"; "name": string; "owner": EditId; "unit": "mm"; "grid": Quantity; "children"?: Array<EditId>; };
export type EditCellData = { "kind": "cell"; "name": string; "owner": EditId; "unit": "um" | "nm"; "grid": Quantity; "technology": EditRef; "children"?: Array<EditId>; "authority": "manual" | "generator" | "native_source"; "source_view"?: string; };
export type EditPinData = { "kind": "pin"; "owner": EditId; "port_id": EditId; "view": "symbol" | "layout"; "position": Point; "orientation_deg"?: number; "layer"?: EditRef; "shape"?: EditId; };
export type EditPinMapData = { "kind": "pin_map"; "owner": EditId; "port_id": EditId; "symbol_pin": EditId; "physical_pins": Array<EditId>; "native_paths"?: Array<string>; };
export type EditNetData = { "kind": "net"; "name"?: string; "parent": EditId; "domain": "electrical" | "optical" | "thermal"; "endpoints": Array<EditEndpoint>; "width": number; };
/** Instance path relative to owning net/sheet parent. Canonical port identity plus explicit bit selection; no geometric contact inference or implicit parent traversal. */
export type EditEndpoint = { "instance_path": Array<EditId>; "port_id": EditId; "bits"?: Array<number>; };
export type EditWireData = { "kind": "wire"; "parent": EditId; "net": EditId; "points": Array<Point>; };
export type EditJunctionData = { "kind": "junction"; "parent": EditId; "net": EditId; "point": Point; };
/** Physical geometry belongs to a cell; it is not automatically a separate circuit component. */
export type EditShapeData = { "kind": "shape"; "parent": EditId; "layer": EditRef; "geometry": ShapeGeometry; "net"?: EditId; };
export type EditLayerData = { "kind": "layer"; "name": string; "owner": EditId; "technology": EditRef; "role": "material" | "contact" | "routing" | "implant" | "well" | "annotation" | "derived"; "color"?: string; "visible"?: boolean; "locked"?: boolean; "output_layer"?: number; "output_datatype"?: number; };
/** Project-contained source bytes are saved through write_source, never executed by reading/cataloging. */
export type EditSourceData = { "kind": "source"; "name": string; "path": string; "format": string; "role": "implementation" | "testbench" | "generator" | "model" | "properties" | "documentation" | "configuration"; "owner"?: EditId; "sha256"?: Hash; };
export type EditScriptData = { "kind": "script"; "name": string; "source": EditRef; "entry"?: string; "profile": EditRef; "description"?: string; };
/** Creating without source generates a persisted editable template from placement, target interface and bench_type. Regeneration is explicit into a new source asset. Benches are harness objects excluded from manufactured circuit. Template provenance is retained for generated sources; target/interface changes mark binding stale and block execution. Production targets cannot overlap; harness wiring is explicit. */
export type EditTestbenchData = { "kind": "testbench"; "name": string; "parent": EditId; "bench_type": "spice" | "hdl" | "cocotb"; "target": EditBenchTarget; "additional_targets"?: Array<EditBenchTarget>; "source"?: EditRef; "template"?: EditRef; "interface_digest"?: Hash; "template_revision"?: string; "analysis"?: SpiceAnalysis; "hdl_language"?: "inherit"; "probes"?: Array<EditBenchProbe>; "schematic_transform"?: Transform; "bindings"?: Array<EditHarnessBinding>; "binding_state"?: "resolved" | "stale" | "missing"; "generated_from"?: { "template": PinnedRef; "target_interface_hash": Hash; "source_hash": Hash; }; };
/** Resolved relative to bench parent occurrence. First ID is a sibling circuit instance; remaining IDs descend inside it. No self, parent, ancestor, unrelated scope or annotation. */
export type EditBenchTarget = { "sibling": EditId; "descendants": Array<EditId>; };
/** Target index 0 is primary, 1..N are declared additional targets. Descendants resolve only within selected DUT subtree; probes never add duplicate DUT instances. */
export type EditBenchProbe = { "target": number; "descendants": Array<EditId>; "port_id": EditId; "bits"?: Array<number>; };
/** Explicit generated/editable harness terminal or signal to canonical target port binding, including extra DUTs; excluded from production netlist. */
export type EditHarnessBinding = { "target": number; "port_id": EditId; "signal": string; "bits"?: Array<number>; };
/** Graphical-only: excluded from netlisting, ERC and fabricated circuit; plot links evidence without adding a device. */
export type EditAnnotationData = { "kind": "annotation"; "parent": EditId; "annotation_type": "text" | "line" | "polyline" | "arrow" | "image" | "plot" | "measurement" | "rectangle" | "ellipse"; "points"?: Array<Point>; "text"?: string; "artifact"?: EditRef; "style"?: { "color"?: string; "width"?: number; "font_size"?: number; "fill"?: string; }; "plot"?: { "run"?: EditId; "signals"?: Array<string>; "x_axis"?: string; "y_axis"?: string; }; };
/** location is resolved by engine-managed/explicitly linked project policy; no path can escape its granted root. */
export type EditProjectData = { "kind": "project"; "name": string; "location"?: string; "top"?: EditId; "config_path": "canvas.toml"; "template"?: EditRef; };

export interface EngineClient {
  describe(requestId: OpaqueId, params: DescribeParams): Promise<DescribeResult>;
  query(requestId: OpaqueId, params: QueryParams): Promise<QueryResult>;
  edit(requestId: OpaqueId, params: EditParams): Promise<EditResult>;
  run(requestId: OpaqueId, params: RunParams): Promise<RunResult>;
  script(requestId: OpaqueId, params: ScriptParams): Promise<ScriptResult>;
  watch(requestId: OpaqueId, params: WatchParams): Promise<WatchResult>;
}
